// Validate Lead Data
// Kiểm tra dữ liệu đầu vào cho lead VN

const lead = $input.first().json.body || $input.first().json;

const errors = [];
const requiredFields = ['name', 'email', 'phone'];

// Check required fields
for (const field of requiredFields) {
  if (!lead[field] || lead[field].trim() === '') {
    errors.push(`Thiếu trường bắt buộc: ${field}`);
  }
}

// Validate email
if (lead.email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(lead.email)) {
    errors.push('Email không hợp lệ');
  }
}

// Validate Vietnamese phone
if (lead.phone) {
  const phoneRegex = /^(\+84|0)[0-9]{9,10}$/;
  const cleanPhone = lead.phone.replace(/[\s\-\.]/g, '');
  if (!phoneRegex.test(cleanPhone)) {
    errors.push('Số điện thoại không hợp lệ. Định dạng: +84XXXXXXXXX hoặc 0XXXXXXXXXX');
  }
  lead.phone = cleanPhone; // Normalize phone
}

// Set defaults
lead.source = lead.source || 'website';
lead.status = 'new';
lead.created_at = new Date().toISOString();
lead.vietnam_time = new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' });

// Lead scoring based on source
const sourceScores = {
  'referral': 90,
  'website': 70,
  'facebook': 60,
  'google': 65,
  'ads': 50,
  'event': 80,
  'email': 40
};
lead.lead_score = sourceScores[lead.source.toLowerCase()] || 50;

// Priority based on score
lead.priority = lead.lead_score >= 80 ? 'high' : 
                lead.lead_score >= 60 ? 'medium' : 'low';

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      errors,
      statusCode: 400
    }
  }];
}

return [{
  json: {
    valid: true,
    lead,
    statusCode: 200
  }
}];

// Check if duplicate exists
const existingLeads = $input.all();
const newLead = $('Validate & Score Lead').first().json.lead;

if (existingLeads.length > 0) {
  // Duplicate found
  const existing = existingLeads[0].json;
  return [{
    json: {
      is_duplicate: true,
      existing_record: existing,
      new_lead: newLead,
      action: 'update',
      message: `Lead đã tồn tại: ${existing.Email || existing.email}`
    }
  }];
} else {
  // New lead
  return [{
    json: {
      is_duplicate: false,
      new_lead: newLead,
      action: 'create',
      message: 'Lead mới - cần tạo record'
    }
  }];
}

